#!/usr/bin/env python3
from __future__ import annotations
import math
from pathlib import Path
OUT=Path('governance/visual_pedagogy/review_candidates/bsd/plate_curve_successor.svg')
def pt(x,y):
    X=150+(x+6)*43.5; Y=845-y*36
    return f'{X:.1f},{Y:.1f}'
def branch(sign):
    a=[]
    for i in range(121):
        x=-6+i*(14/120); q=x*x*x-25*x
        if q>=0: a.append(pt(x,sign*math.sqrt(q)))
    return ' '.join(a)
def render():
    p=(25/4,75/8); P=pt(*p); Pr=pt(p[0],-p[1]); upper=branch(1); lower=branch(-1)
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 1600" role="img" aria-labelledby="t d"><title id="t">A Rational Point Opens a Door</title><desc id="d">A deterministic plot of E5, y squared equals x cubed minus 25x, highlights P equals 25 over 4 comma 75 over 8 and connects it to an exact rational right triangle of area five.</desc><defs><linearGradient id="p" x2="1" y2="1"><stop stop-color="#fff8e8"/><stop offset="1" stop-color="#e6d2aa"/></linearGradient><linearGradient id="n" x2="1" y2="1"><stop stop-color="#07182f"/><stop offset="1" stop-color="#214d69"/></linearGradient><radialGradient id="g"><stop stop-color="#ffe9a0" stop-opacity=".8"/><stop offset="1" stop-color="#bd913a" stop-opacity="0"/></radialGradient><filter id="s"><feDropShadow dy="10" stdDeviation="10" flood-opacity=".28"/></filter><clipPath id="plot"><rect x="125" y="365" width="680" height="670" rx="20"/></clipPath></defs><rect width="1200" height="1600" fill="#07182f"/><rect x="20" y="20" width="1160" height="1560" rx="8" fill="none" stroke="#bd913a" stroke-width="3"/><rect x="70" y="75" width="1060" height="1450" rx="18" fill="url(#p)" stroke="#bd913a" stroke-width="3" filter="url(#s)"/><text x="600" y="130" text-anchor="middle" font-family="Arial" font-size="17" letter-spacing="5" fill="#07182f">GRAND CHALLENGE LABS</text><text x="600" y="190" text-anchor="middle" font-family="Arial" font-size="18" letter-spacing="3" fill="#bd913a">BIRCH–SWINNERTON-DYER · PLATE I</text><text x="600" y="250" text-anchor="middle" font-family="Georgia" font-size="48" fill="#07182f">A Rational Point Opens a Door</text><text x="600" y="302" text-anchor="middle" font-family="Georgia" font-size="22" font-style="italic" fill="#776f62">One exact witness joins a cubic curve to an ancient question about area.</text><rect x="125" y="365" width="680" height="670" rx="20" fill="url(#n)" stroke="#bd913a" stroke-width="3"/><circle cx="480" cy="680" r="260" fill="url(#g)"/><line x1="150" y1="845" x2="780" y2="845" stroke="#f5ead2" stroke-width="2" opacity=".6"/><line x1="411" y1="405" x2="411" y2="1000" stroke="#f5ead2" stroke-width="2" opacity=".6"/><g clip-path="url(#plot)"><polyline points="{upper}" fill="none" stroke="#e4c678" stroke-width="5"/><polyline points="{lower}" fill="none" stroke="#8ec0c7" stroke-width="4"/></g><circle cx="{P.split(',')[0]}" cy="{P.split(',')[1]}" r="10" fill="#fff2a9" stroke="#a84b3e" stroke-width="3"/><circle cx="{Pr.split(',')[0]}" cy="{Pr.split(',')[1]}" r="7" fill="#fff2a9" opacity=".55"/><text x="690" y="505" font-family="Georgia" font-size="22" fill="#fff8e8">E₅ : y² = x³ − 25x</text><text x="690" y="545" font-family="Arial" font-size="16" font-weight="700" fill="#e4c678">P = (25/4, 75/8)</text><path d="M805 700H895" stroke="#bd913a" stroke-width="5"/><polygon points="895,700 875,688 875,712" fill="#bd913a"/><rect x="850" y="445" width="240" height="480" rx="18" fill="#fffaf0" stroke="#bd913a" stroke-width="2"/><text x="970" y="490" text-anchor="middle" font-family="Arial" font-size="14" font-weight="700" letter-spacing="2" fill="#bd913a">EXACT TRIANGLE</text><path d="M895 780H1050L895 545Z" fill="#dbe9ec" stroke="#315f7a" stroke-width="5"/><path d="M895 750H925V780" fill="none" stroke="#bd913a" stroke-width="4"/><text x="972" y="815" text-anchor="middle" font-family="Georgia" font-size="19" fill="#07182f">3/2</text><text x="875" y="675" text-anchor="middle" font-family="Georgia" font-size="19" fill="#07182f" transform="rotate(-90 875 675)">20/3</text><text x="997" y="635" text-anchor="middle" font-family="Georgia" font-size="19" fill="#07182f" transform="rotate(-56 997 635)">41/6</text><text x="970" y="865" text-anchor="middle" font-family="Georgia" font-size="22" font-weight="700" fill="#557b64">Area = 5</text><text x="970" y="897" text-anchor="middle" font-family="Georgia" font-size="15" fill="#776f62">½·(3/2)·(20/3)=5</text><rect x="145" y="1100" width="910" height="210" rx="14" fill="#fffaf0" stroke="#bd913a" stroke-width="2"/><text x="600" y="1140" text-anchor="middle" font-family="Arial" font-size="15" font-weight="700" letter-spacing="3" fill="#bd913a">ONE ARITHMETIC OBJECT · TWO VIEWS</text><text x="600" y="1190" text-anchor="middle" font-family="Georgia" font-size="21" fill="#07182f">The point is exact. The triangle is exact. The plotted window is finite.</text><text x="600" y="1230" text-anchor="middle" font-family="Georgia" font-size="19" font-style="italic" fill="#776f62">Finding a rational point opens the door; it does not certify the whole Mordell–Weil group.</text><text x="600" y="1275" text-anchor="middle" font-family="Arial" font-size="14" font-weight="700" fill="#a84b3e">NO RANK OR BSD CLAIM IS MADE BY THE PLOT</text><line x1="150" y1="1450" x2="1050" y2="1450" stroke="#bd913a"/><text x="600" y="1487" text-anchor="middle" font-family="Arial" font-size="15" font-weight="700" letter-spacing="2" fill="#776f62">DATA-DERIVED PEDAGOGICAL PLATE · NOT PROOF AUTHORITY</text></svg>'''
def main(): OUT.parent.mkdir(parents=True,exist_ok=True); OUT.write_text(render(),encoding='utf-8')
if __name__=='__main__': main()
